pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),resultArea=document.getElementById("result-area"),notesContent=document.getElementById("notes-content"),dropZone=document.getElementById("drop-zone");function generateNotes(e){loading.style.display="none",resultArea.style.display="block";const t=e.split(/(?<=[.!?])\s+|\n/),n=[];let o={title:"Introduction",points:[]};t.forEach(e=>{const t=e.trim();t.length<10||(t.length<50&&(t===t.toUpperCase()||/^\d+\./.test(t))?(o.points.length>0&&n.push(o),o={title:t,points:[]}):t.length>60&&o.points.push(t))}),n.push(o);let s="";n.slice(0,8).forEach(e=>{s+=`\n                    <div class="note-section">\n                        <h3>${e.title}</h3>\n                        ${e.points.slice(0,4).map(e=>`<div class="note-item">${e}</div>`).join("")}\n                    </div>`}),notesContent.innerHTML=s,setTimeout(()=>{downloadPDF(n)},2e3),document.getElementById("download-btn").onclick=()=>downloadPDF(n)}function downloadPDF(e){const{jsPDF:t}=window.jspdf,n=new t;let o=20;n.setFontSize(22),n.setTextColor(250,114,32),n.text("Academic Study Guide",20,o),o+=15,n.setFontSize(10),n.setTextColor(150),n.text("Generated by PDFIndi AI Engine",20,o),o+=15,e.slice(0,10).forEach(e=>{o>270&&(n.addPage(),o=20),n.setFontSize(14),n.setTextColor(0),n.text(e.title,20,o),o+=8,n.setFontSize(10),n.setTextColor(80),e.points.slice(0,5).forEach(e=>{const t=n.splitTextToSize("• "+e,170);n.text(t,25,o),o+=5*t.length+2,o>270&&(n.addPage(),o=20)}),o+=5}),n.save("pdfindi-study-notes.pdf")}fileInput.onchange=async e=>{const t=e.target.files[0];if(t){dropZone.style.display="none",loading.style.display="block";try{const e=await t.arrayBuffer(),n=await pdfjsLib.getDocument(e).promise;document.getElementById("doc-title").innerText=t.name.replace(".pdf","")+" - Study Guide";let o="";for(let e=1;e<=n.numPages;e++){const t=await n.getPage(e);o+=(await t.getTextContent()).items.map(e=>e.str).join(" ")+"\n"}generateNotes(o)}catch(e){alert("Error processing PDF."),location.reload()}}};